using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class FixTaskLightColliders {
 static string H=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../../SourceAssets/B4_DeskAndCollision/"));
 static Vector3[] centers={new Vector3(0,.049f,-.25f),new Vector3(0,1.21f,-.38f),new Vector3(0,2.37f,.03f),new Vector3(0,2.356f,.40f),new Vector3(0,1.1f,-.285f)};
 static Vector3[] sizes={new Vector3(.48f,.098f,.62f),new Vector3(.072f,2.34f,.082f),new Vector3(.12f,.13f,.82f),new Vector3(.82f,.132f,.19f),new Vector3(.13f,.24f,.12f)};
 static float[] V(Vector3 p)=>new[]{p.x,p.y,p.z};
 static object Probe(Transform t){var cols=t.GetComponents<Collider>();int ghost=0,solid=0;for(int i=-3;i<=3;i++){Vector3 p=t.TransformPoint(new Vector3(i*.09f,1,.38f));if(cols.Any(c=>c.enabled&&(c.ClosestPoint(p)-p).sqrMagnitude<.0000001f))ghost++;}Vector3 mast=t.TransformPoint(new Vector3(0,1.2f,-.38f));if(cols.Any(c=>c.enabled&&(c.ClosestPoint(mast)-mast).sqrMagnitude<.0000001f))solid++;return new{name=t.name,emptySpaceBlocked=ghost,mastBlocked=solid};}
 static object Walk(Transform t,CharacterController cc){var save=cc.transform.position;bool e=cc.enabled;var results=new List<object>();try{foreach(bool rev in new[]{false,true}){var a=t.TransformPoint(new Vector3(rev?.98f:-.98f,0,.43f));var b=t.TransformPoint(new Vector3(rev?-.98f:.98f,0,.43f));cc.enabled=false;cc.transform.position=a+Vector3.up*(cc.height*.5f-cc.center.y+.04f);cc.enabled=true;Physics.SyncTransforms();float remaining=99;for(int i=0;i<140;i++){var d=b-cc.transform.position;d.y=0;remaining=d.magnitude;if(remaining<.04f)break;cc.Move(d.normalized*Mathf.Min(.045f,remaining)+Vector3.down*.035f);}results.Add(new{reverse=rev,passed=remaining<.12f,remaining,end=V(cc.transform.position)});}}finally{cc.enabled=false;cc.transform.position=save;cc.enabled=e;Physics.SyncTransforms();}return new{name=t.name,results};}
 public static object Run(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty||!s.path.EndsWith("Level_B4_Circular.unity"))throw new Exception("Saved B4 edit mode required");Directory.CreateDirectory(H);if(!File.Exists(H+"before.unity"))EditorSceneManager.SaveScene(s,H+"before.unity",true);var ts=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).Where(t=>t.gameObject.activeInHierarchy&&t.name.Contains("_TaskLightPole_")&&t.GetComponent<MeshFilter>()).ToArray();var cc=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CharacterController>()).Single();var specific=ts.Where(t=>t.name=="B4_E02_TaskLightPole_13"||t.name=="B4_C02_TaskLightPole_15").ToArray();var before=ts.Select(Probe).ToArray();var walkBefore=specific.Select(t=>Walk(t,cc)).ToArray();var changes=new List<object>();foreach(var t in ts){var old=t.GetComponents<BoxCollider>();if(old.Length!=1)throw new Exception("Unexpected collider layout "+t.name);var c=old[0];changes.Add(new{name=t.name,id=GlobalObjectId.GetGlobalObjectIdSlow(t).ToString(),oldCenter=V(c.center),oldSize=V(c.size),newCount=centers.Length});for(int i=0;i<centers.Length;i++){var b=i==0?c:t.gameObject.AddComponent<BoxCollider>();b.center=centers[i];b.size=sizes[i];b.isTrigger=false;PrefabUtility.RecordPrefabInstancePropertyModifications(b);}}Physics.SyncTransforms();var after=ts.Select(Probe).ToArray();var walkAfter=specific.Select(t=>Walk(t,cc)).ToArray();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);var result=new{fixedLights=ts.Length,changes,before,after,walkBefore,walkAfter};File.WriteAllText(H+"collider_fix.json",JsonConvert.SerializeObject(result,Formatting.Indented));EditorSceneManager.OpenScene(s.path);return new{fixedLights=ts.Length,walkBefore,walkAfter};}
}
